export default function ActivityList({ sessions }) {
  return (
    <div className="activity-list">
      {sessions.slice(0, 10).map((s, i) => (
        <div key={i} className="activity-item">
          <span>{new URL(s.domain).hostname}</span>
          <span>{s.duration}s</span>
        </div>
      ))}
    </div>
  );
}
